from dataclasses import FrozenInstanceError
from decimal import Decimal

import pytest

from payment.domain.money import Money


def test_a_currency_is_normalised_to_upper_case() -> None:
    assert Money(Decimal("1"), "eur").currency == "EUR"


@pytest.mark.parametrize("amount", ["0", "-1", "-0.5"])
def test_a_non_positive_amount_is_rejected(amount: str) -> None:
    with pytest.raises(ValueError, match="positive"):
        Money(Decimal(amount), "EUR")


@pytest.mark.parametrize("amount", ["1", "0.01"])
def test_a_small_positive_amount_is_accepted(amount: str) -> None:
    assert Money(Decimal(amount), "EUR").amount == Decimal(amount)


@pytest.mark.parametrize("currency", ["", "   "])
def test_a_blank_currency_is_rejected(currency: str) -> None:
    with pytest.raises(ValueError, match="currency"):
        Money(Decimal("1"), currency)


def test_money_is_immutable() -> None:
    money = Money(Decimal("1"), "EUR")
    with pytest.raises(FrozenInstanceError):
        money.amount = Decimal("2")  # type: ignore[misc]


def test_money_with_same_values_is_equal() -> None:
    assert Money(Decimal("1"), "eur") == Money(Decimal("1"), "EUR")
E
cat >> tests/unit/test_authorize_payment.py <<'E'


def test_the_receipt_records_currency_amount_and_outcome() -> None:
    receipts = InMemoryReceiptStore()
    handler = AuthorizePayment(AlwaysAnswers(AuthorizationOutcome.DECLINED), receipts)

    handler.handle("ORD-3", Money(Decimal("42.50"), "eur"))

    assert receipts.saved == {"ORD-3": "EUR 42.50 -> DECLINED"}


def test_the_handler_cannot_be_subclassed() -> None:
    assert getattr(AuthorizePayment, "__final__", False) is True
